ems":{"$ref":"#/$defs/uuid"},"maxItems":10000,"uniqueItems":true},"works":{"type":"array","items":{"$ref":"#/$defs/work"},"maxItems":10000},"celebratedDays":{"type":"array","items":{"$ref":"#/$defs/date"},"maxItems":10000,"uniqueItems":true},"dayFinishState":{"description":"Latest per-day finish state; null when no day finish state exists. The key is always written; null is never omitted.","anyOf":[{"$ref":"#/$defs/dayFinishState"},{"type":"null"}]},"automaticRandom":{"type":"boolean"}},"required":["fragments","rewardedTaskIDs","unlockedArtworkIDs","dayArtworkIDs","completedTaskIDs","works","celebratedDays","dayFinishState","automaticRandom"],"additionalProperties":false},"work":{"type":"object","description":"Snapshot of one finished day's puzzle work. imagePath references the completed artwork in object storage and is uploaded before the state carrying it is committed; the binary itself never travels through this contract.","properties":{"day":{"$ref":"#/$defs/date"},"artworkID":{"$ref":"#/$defs/artworkID"},"tasks":{"type":"array","items":{"$ref":"#/$defs/workTask"},"maxItems":1000},"imagePath":{"description":"Object storage path of the finished artwork, or null when no image was produced. The key is always written; null is never omitted.","anyOf":[{"type":"string","maxLength":1024},{"type":"null"}]}},"required":["day","artworkID","tasks","imagePath"],"additionalProperties":false},"workTask":{"type":"object","description":"Task snapshot inside a work entry; a denormalized copy that stays meaningful even if the task is later deleted from tasks[].","properties":{"id":{"$ref":"#/$defs/uuid"},"title":{"type":"string","maxLength":500},"slots":{"type":"array","items":{"type":"integer"},"maxItems":96},"isPinned":{"type":"boolean","description":"Optional; omitted means false."}},"required":["id","title","slots"],"additionalProperties":false}}}$contract$::jsonb);
